#!/usr/bin/env python3
"""File line-budget checker (AGENTS.md section 4).

Every source file must stay at or below the ceiling. Files that predate the
ceiling are frozen in tools/line-budget-baseline.txt: they may shrink, never
grow, and the entry disappears when the file is split or deleted.

A file may be exempted only by a marker in its first two lines:

    // line-budget: exempt (generated by tools/gen_api_client.py - do not edit)

The reason is required, and the exempt list is printed on every run so it stays
visible instead of growing quietly.

Usage:
    python3 tools/check_line_budget.py [--root DIR] [--ceiling N]

Exit status: 0 when every file is within budget, 1 otherwise.
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

CEILING = 200
WARN_BAND = 160

SOURCE_SUFFIXES = {".rs", ".py", ".js", ".css", ".html", ".sh"}

# Directories that are not this repo's source: build output, vendored or
# fetched upstream trees, and generated artifacts.
SKIP_DIRS = {
    ".git", "target", "third_party", "vendor", "node_modules",
    "downloads", "build", "dist", "__pycache__",
}

BASELINE_NAME = "line-budget-baseline.txt"
EXEMPT_MARKER = "line-budget: exempt"


def source_files(root: Path) -> list[Path]:
    found = []
    for path in root.rglob("*"):
        if not path.is_file() or path.suffix not in SOURCE_SUFFIXES:
            continue
        if any(part in SKIP_DIRS for part in path.relative_to(root).parts):
            continue
        found.append(path)
    return sorted(found)


def line_count(path: Path) -> int:
    return len(path.read_text(encoding="utf-8", errors="replace").splitlines())


def exemption(path: Path) -> str | None:
    """The reason a file is exempt, or None."""
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines()[:2]:
        if EXEMPT_MARKER in line:
            _, _, reason = line.partition("(")
            return reason.rstrip(")").strip() or "no reason given"
    return None


def load_baseline(path: Path) -> dict[str, int]:
    frozen: dict[str, int] = {}
    if not path.exists():
        return frozen
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        name, _, size = line.rpartition(" ")
        frozen[name] = int(size)
    return frozen


def main() -> int:
    parser = argparse.ArgumentParser(description="Check the file line budget.")
    parser.add_argument("--root", default=".", help="repository root")
    parser.add_argument("--ceiling", type=int, default=CEILING)
    args = parser.parse_args()

    root = Path(args.root).resolve()
    frozen = load_baseline(root / "tools" / BASELINE_NAME)

    over, grew, exempt, band = [], [], [], []
    for path in source_files(root):
        name = path.relative_to(root).as_posix()
        size = line_count(path)

        reason = exemption(path)
        if reason is not None:
            exempt.append((name, size, reason))
            continue

        budget = min(args.ceiling, frozen.get(name, args.ceiling))
        if size > budget:
            (grew if name in frozen else over).append((name, size, budget))
        elif name not in frozen and size > WARN_BAND:
            band.append((name, size))

    for name, size, reason in exempt:
        print(f"exempt  {name} ({size} lines): {reason}")
    for name, size in band:
        print(f"warn    {name}: {size} lines, ceiling {args.ceiling}")
    for name, size, budget in grew:
        print(f"GREW    {name}: {size} lines, frozen at {budget} - split it, do not add to it")
    for name, size, budget in over:
        print(f"OVER    {name}: {size} lines, ceiling {budget} - name the seam, do not shuffle code")

    print()
    print(f"{len(exempt)} exempt, {len(band)} in the warning band, "
          f"{len(grew)} frozen files grew, {len(over)} over the ceiling")
    if grew or over:
        return 1
    print("line budget OK")
    return 0


if __name__ == "__main__":
    sys.exit(main())
